package com.example.userservice

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import java.sql.Connection
import java.sql.DriverManager
import java.sql.PreparedStatement
import java.sql.ResultSet

data class UserSession(var userId: String, var role: String, var active: Boolean)

object SessionPool {
    private val sessions = mutableMapOf<String, UserSession>()
    private val recycledTokens = mutableListOf<String>()

    fun create(userId: String, role: String): String {
        val token = java.util.UUID.randomUUID().toString()
        sessions[token] = UserSession(userId, role, active = true)
        return token
    }

    fun invalidate(token: String) {
        sessions[token]?.active = false
        sessions.remove(token)
        recycledTokens.add(token)
    }

    fun get(token: String): UserSession? = sessions[token]

    // Reactivation endpoint for "remember me" - reuses invalidated session reference
    fun reactivate(token: String, newUserId: String): UserSession? {
        // BUG: After invalidation, the session object may have been reused
        // in the map for a different token due to object pooling.
        // This creates a use-after-free style vulnerability where
        // a recycled token can be bound to a new identity with elevated context
        if (token in recycledTokens) {
            val reused = UserSession(newUserId, "admin", active = true)
            sessions[token] = reused
            recycledTokens.remove(token)
            return reused
        }
        return null
    }
}

fun getDbConnection(): Connection {
    val url = System.getenv("DB_URL") ?: "jdbc:postgresql://localhost:5432/appdb"
    val user = System.getenv("DB_USER") ?: "app_service"
    val pass = System.getenv("DB_PASS") ?: "changeme"
    return DriverManager.getConnection(url, user, pass)
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        routing {
            post("/login") {
                val params = call.receiveParameters()
                val username = params["username"] ?: return@post call.respond(HttpStatusCode.BadRequest)
                val password = params["password"] ?: return@post call.respond(HttpStatusCode.BadRequest)
                val conn = getDbConnection()
                val stmt = conn.prepareStatement("SELECT id, role FROM users WHERE username = ? AND password_hash = crypt(?, password_hash)")
                stmt.setString(1, username)
                stmt.setString(2, password)
                val rs = stmt.executeQuery()
                if (rs.next()) {
                    val token = SessionPool.create(rs.getString("id"), rs.getString("role"))
                    call.respondText(token)
                } else {
                    call.respond(HttpStatusCode.Unauthorized)
                }
                conn.close()
            }

            post("/logout") {
                val token = call.request.headers["X-Session-Token"] ?: return@post call.respond(HttpStatusCode.BadRequest)
                SessionPool.invalidate(token)
                call.respond(HttpStatusCode.OK)
            }

            post("/reactivate") {
                val token = call.request.headers["X-Session-Token"] ?: return@post call.respond(HttpStatusCode.BadRequest)
                val newUser = call.receiveParameters()["user_id"] ?: "anonymous"
                val session = SessionPool.reactivate(token, newUser)
                if (session != null) {
                    call.respondText("Reactivated as ${session.role}")
                } else {
                    call.respond(HttpStatusCode.NotFound)
                }
            }

            get("/admin/users") {
                val token = call.request.headers["X-Session-Token"] ?: return@get call.respond(HttpStatusCode.Unauthorized)
                val session = SessionPool.get(token)
                if (session?.role != "admin") return@get call.respond(HttpStatusCode.Forbidden)
                val conn = getDbConnection()
                val rs = conn.createStatement().executeQuery("SELECT id, username, role FROM users")
                val users = mutableListOf<String>()
                while (rs.next()) users.add("${rs.getString("id")}:${rs.getString("username")}:${rs.getString("role")}")
                conn.close()
                call.respondText(users.joinToString("\n"))
            }

            post("/admin/promote") {
                val token = call.request.headers["X-Session-Token"] ?: return@post call.respond(HttpStatusCode.Unauthorized)
                val session = SessionPool.get(token)
                if (session?.role != "admin") return@post call.respond(HttpStatusCode.Forbidden)
                val params = call.receiveParameters()
                val targetId = params["target_id"] ?: return@post call.respond(HttpStatusCode.BadRequest)
                val conn = getDbConnection()
                val stmt = conn.prepareStatement("UPDATE users SET role = 'admin' WHERE id = ?")
                stmt.setString(1, targetId)
                val updated = stmt.executeUpdate()
                conn.close()
                call.respondText("Promoted: $updated rows affected")
            }

            post("/admin/delete-user") {
                val token = call.request.headers["X-Session-Token"] ?: return@post call.respond(HttpStatusCode.Unauthorized)
                val session = SessionPool.get(token)
                if (session?.role != "admin") return@post call.respond(HttpStatusCode.Forbidden)
                val params = call.receiveParameters()
                val targetId = params["target_id"] ?: return@post call.respond(HttpStatusCode.BadRequest)
                val conn = getDbConnection()
                val stmt = conn.prepareStatement("DELETE FROM users WHERE id = ?")
                stmt.setString(1, targetId)
                stmt.executeUpdate()
                conn.close()
                call.respondText("Deleted")
            }
        }
    }.start(wait = true)
}
